def get_path(item: dict, path: tuple) -> object:
    value: object = item
    for key in path:
        value = value[key]  # type: ignore[index]
    return value


def set_path(item: dict, path: tuple, value: object) -> None:
    parent = item
    for key in path[:-1]:
        parent = parent[key]  # type: ignore[index]
    parent[path[-1]] = value


def guarded_value(item: dict, path: tuple, before: object, after: object, label: str, future_values: tuple = ()) -> bool:
    current = get_path(item, path)
    if current == before:
        set_path(item, path, after)
        return True
    if current == after or current in future_values:
        return False
    raise ValueError(f"unexpected value at {label}: {path}")


def guarded_replace(item: dict, path: tuple, before: str, after: str, label: str, future_after: tuple = ()) -> bool:
    current = get_path(item, path)
    if not isinstance(current, str):
        raise ValueError(f"non-text replacement target at {label}: {path}")
    before_count = current.count(before)
    after_count = current.count(after)
    if after_count == 1:
        return False
    if before_count == 1 and after_count == 0:
        set_path(item, path, current.replace(before, after, 1))
        return True
    if before_count == 0 and any(value in current for value in future_after):
        return False
    raise ValueError(f"guarded replacement mismatch at {label}: before={before_count}, after={after_count}")


def known_replacement_states(text_id: str, path: tuple, value: object) -> tuple:
    """Return each guarded intermediate state as well as the final value.

    This keeps --prepare idempotent when a later reviewed refinement is added
    after an earlier version of the same field was already applied.
    """
    if not isinstance(value, str):
        return (value,)
    states = []
    for replacement_id, replacement_path, before, after in TEXT_REPLACEMENTS:
        if replacement_id == text_id and replacement_path == path and before in value:
            value = value.replace(before, after, 1)
            states.append(value)
    return tuple(states) or (value,)


def apply_edits(text_by_id: dict) -> bool:
    changed = False
    for index, (text_id, path, before, after) in enumerate(FIELD_EDITS):
        item = text_by_id.get(text_id)
        if item is None or item.get("level") != "B1":
            raise ValueError(f"missing or wrong-level source text: {text_id}")
        future = tuple(next_after for next_id, next_path, _, next_after in FIELD_EDITS[index + 1:]
                       if next_id == text_id and next_path == path)
        transformed = tuple(state for value in (after, *future) for state in known_replacement_states(text_id, path, value))
        changed |= guarded_value(item, path, before, after, text_id, future + transformed)
    for index, (text_id, path, before, after) in enumerate(TEXT_REPLACEMENTS):
        item = text_by_id.get(text_id)
        if item is None or item.get("level") != "B1":
            raise ValueError(f"missing or wrong-level source text: {text_id}")
        future = tuple(next_after for next_id, next_path, _, next_after in TEXT_REPLACEMENTS[index + 1:]
                       if next_id == text_id and next_path == path)
        changed |= guarded_replace(item, path, before, after, text_id, future)
    questions = {
        question["id"]: question
        for item in text_by_id.values()
        for question in item.get("questions", [])
    }
    for index, (question_id, key, before, after) in enumerate(QUESTION_EDITS):
        question = questions.get(question_id)
        if question is None:
            raise ValueError(f"missing question: {question_id}")
        future = tuple(next_after for next_id, next_key, _, next_after in QUESTION_EDITS[index + 1:]
                       if next_id == question_id and next_key == key)
        changed |= guarded_value(question, (key,), before, after, question_id, future)
    return changed


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--prepare", action="store_true", help="apply guarded text/question corrections before TTS")
    args = parser.parse_args()

    texts = json.loads(TEXTS_FILE.read_text(encoding="utf-8"))
    text_by_id = {item["id"]: item for item in texts}
    if len(text_by_id) != len(texts):
        raise ValueError("duplicate text ids")
    changed = apply_edits(text_by_id)
    target_texts = [text_by_id[text_id] for text_id in TARGET_IDS]
    if any(item.get("level") != "B1" or item.get("neu") is not True for item in target_texts):
        raise ValueError("R165 sources must be the selected B1 texts marked neu")
    for item in target_texts:
        for question in item.get("questions", []):
            if question.get("type") not in {"mc", "truefalse", "fill"}:
                raise ValueError(f"unsupported question type: {question.get('id')}")
            answer = question.get("answer")
            if question.get("type") == "fill":
                if not isinstance(answer, list) or not answer:
                    raise ValueError(f"invalid fill answer: {question.get('id')}")
            elif answer not in question.get("options", []):
                raise ValueError(f"question answer absent from options: {question.get('id')}")
    if changed:
        TEXTS_FILE.write_text(json.dumps(texts, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    counts = {item["id"]: len(item["de"].split()) for item in target_texts}
    print("R165 reviewed German word counts:", json.dumps(counts, ensure_ascii=False))
    print("R165 question count:", sum(len(item.get("questions", [])) for item in target_texts))
    if args.prepare:
        print("R165 prepare complete; generate audio from the current de fields before finalizing the manifest.")
        return

    if not SOURCE_SHA256:
        raise ValueError("populate SOURCE_SHA256 after reviewing and generating the exact source strings")
    for item in target_texts:
        digest = hashlib.sha256(item["de"].encode("utf-8")).hexdigest()
        if SOURCE_SHA256.get(item["id"]) != digest:
            raise ValueError(f"R165 audio source text hash mismatch: {item['id']}")

    manifest = json.loads(MANIFEST_FILE.read_text(encoding="utf-8"))
    entries = manifest.get("einsaetze", [])
    existing = {entry["id"]: entry for entry in entries}
    if len(existing) != len(entries) or manifest.get("count") != len(entries) or len(entries) < 122:
        raise ValueError(f"unexpected HörLabor manifest state: count={manifest.get('count')} entries={len(entries)}")
    dialog_ids = {entry["id"] for entry in json.loads((ROOT / "content" / "dialog-audio.json").read_text(encoding="utf-8")).get("einsaetze", [])}
    diktat_ids = {entry["id"] for entry in json.loads((ROOT / "content" / "diktat-audio.json").read_text(encoding="utf-8")).get("einsaetze", [])}
    added = 0
    updated = 0
    for item in target_texts:
        text_id = item["id"]
        if len(item.get("questions", [])) != 4:
            raise ValueError(f"unexpected question count: {text_id}")
        if text_id in dialog_ids or text_id in diktat_ids:
            raise ValueError(f"cross-manifest audio assignment: {text_id}")
        path = AUDIO_DIR / f"{text_id}.mp3"
        if not path.is_file() or path.stat().st_size < 8000:
            raise ValueError(f"missing or undersized MP3: {path}")
        data = path.read_bytes()
        frames = mp3_frame_count(data)
        if data[:3] != b"ID3":
            raise ValueError(f"missing ID3v2 header: {text_id}")
        expected = {
            "id": text_id,
            "file": f"/audio/hoeren/{text_id}.mp3",
            "voice": VOICE,
            "level": "B1",
            "bytes": len(data),
        }
        old = existing.get(text_id)
        if old is None:
            entries.append(expected)
            existing[text_id] = expected
            added += 1
        elif any(old.get(key) != value for key, value in expected.items()):
            if old.get("id") != text_id or old.get("file") != expected["file"] or old.get("level") != "B1":
                raise ValueError(f"refusing to change non-R165 manifest identity: {text_id}")
            old.update(expected)
            updated += 1
        print(f"✓ {text_id}: {len(item['de'].split())} words · {len(data)} bytes · {frames} MPEG Layer III frames")

    manifest_ids = {entry["id"] for entry in entries}
    disk_ids = {path.stem for path in AUDIO_DIR.glob("*.mp3")}
    if manifest_ids != disk_ids:
        raise ValueError(f"manifest/disk mismatch: disk-only={disk_ids - manifest_ids}, manifest-only={manifest_ids - disk_ids}")
    if not set(TARGET_IDS).issubset(manifest_ids):
        raise ValueError(f"R165 IDs missing from manifest: {set(TARGET_IDS) - manifest_ids}")
    if added or updated:
        manifest["count"] = len(entries)
        manifest["updated"] = date.today().isoformat()
        MANIFEST_FILE.write_text(json.dumps(manifest, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    print(f"R165: {added} new manifest entries · {updated} refreshed entries · {manifest['count']} HörLabor files total")


if __name__ == "__main__":
    main()
